import{_ as r,C as s,o as l,c as o,a4 as t,E as i}from"./chunks/framework.DAD9IEko.js";const k=JSON.parse('{"title":"PP-09 三电平 SVPWM","description":"","frontmatter":{"date":"2026-06-11T00:00:00.000Z","section":"电机控制","chapter":"power-path","chapterTitle":"功率链路","chapterOrder":40,"category":"功率链路","source":"motor","visibility":"public","title":"PP-09 三电平 SVPWM","tags":["motor-control"],"status":"learning","summary":"> **状态**: reviewed > **范围**: 本模块建立三电平 SVPWM 的理论和仿真闭环，不要求 lxfoc 在 70% 阶段输出三电平硬件 PWM。","navGroup":"基础与硬件","navGroupOrder":20},"headers":[],"relativePath":"content/motor/power-path/PP-09-Three-Level-SVPWM.md","filePath":"content/motor/power-path/PP-09-Three-Level-SVPWM.md","lastUpdated":1783181958000}'),d={name:"content/motor/power-path/PP-09-Three-Level-SVPWM.md"};function n(h,a,p,c,u,b){const e=s("MermaidDiagram");return l(),o("div",null,[a[0]||(a[0]=t('<h1 id="pp-09-三电平-svpwm" tabindex="-1">PP-09 三电平 SVPWM <a class="header-anchor" href="#pp-09-三电平-svpwm" aria-label="Permalink to &quot;PP-09 三电平 SVPWM&quot;">​</a></h1><blockquote><p><strong>状态</strong>: reviewed<br><strong>范围</strong>: 本模块建立三电平 SVPWM 的理论和仿真闭环，不要求 lxfoc 在 70% 阶段输出三电平硬件 PWM。</p></blockquote><p><strong>模块编号：</strong> PP-09<br><strong>模块名称：</strong> 三电平 SVPWM<br><strong>文档版本：</strong> v1.1<br><strong>前置知识：</strong> PP-08 三电平拓扑基础、ALG-01 FOC 理论基础、EE-08 整流与逆变拓扑<br><strong>难度等级：</strong></p><hr><h2 id="_1-核心摘要" tabindex="-1">1. 核心摘要 <a class="header-anchor" href="#_1-核心摘要" aria-label="Permalink to &quot;1.  核心摘要&quot;">​</a></h2><p><strong>一句话：</strong> 三电平 SVPWM 是把 FOC 输出的 <code>u_alpha/u_beta</code> 电压矢量映射为 P/O/N 三状态桥臂序列的调制方法；它不仅要合成目标电压，还要利用冗余小矢量维持中点电位平衡。</p><p><strong>认知挂钩：</strong> 二电平 SVPWM 像在一个大六边形里用 6 个方向的箭头拼目标矢量；三电平 SVPWM 把这个大六边形切成更多小三角形。小三角形让电压合成更细腻，但目标点落在哪个小三角形、选哪组冗余矢量、怎样修正中点电压，都必须由调制器决定。</p><p><strong>核心问题链：</strong></p>',8)),i(e,{code:"flowchart%20TD%0A%20%20A%5B%22FOC%20%E8%BE%93%E5%87%BA%20u_alpha%2Fu_beta%22%5D%20--%3E%20B%5B%22%E5%88%A4%E6%96%AD%E7%9B%AE%E6%A0%87%E7%9F%A2%E9%87%8F%E6%89%80%E5%9C%A8%E6%89%87%E5%8C%BA%E5%92%8C%E5%B0%8F%E4%B8%89%E8%A7%92%E5%BD%A2%22%5D%0A%20%20B%20--%3E%20C%5B%22%E9%80%89%E6%8B%A9%E7%9B%B8%E9%82%BB%E4%B8%89%E7%94%B5%E5%B9%B3%E7%A9%BA%E9%97%B4%E7%9F%A2%E9%87%8F%22%5D%0A%20%20C%20--%3E%20D%5B%22%E8%AE%A1%E7%AE%97%E4%BD%9C%E7%94%A8%E6%97%B6%E9%97%B4%20T1%2FT2%2FT3%22%5D%0A%20%20D%20--%3E%20E%5B%22%E9%80%89%E6%8B%A9%E5%86%97%E4%BD%99%E5%B0%8F%E7%9F%A2%E9%87%8F%22%5D%0A%20%20E%20--%3E%20F%5B%22%E8%BE%93%E5%87%BA%E6%AF%8F%E7%9B%B8%20P%2FO%2FN%20%E7%8A%B6%E6%80%81%E6%97%B6%E9%97%B4%22%5D%0A"}),a[1]||(a[1]=t(`<hr><h2 id="_2-问题引入" tabindex="-1">2. 问题引入 <a class="header-anchor" href="#_2-问题引入" aria-label="Permalink to &quot;2.  问题引入&quot;">​</a></h2><h3 id="工程师的真实困惑" tabindex="-1">工程师的真实困惑 <a class="header-anchor" href="#工程师的真实困惑" aria-label="Permalink to &quot;工程师的真实困惑&quot;">​</a></h3><blockquote><p><strong>场景 1：二电平 SVPWM 代码不能直接套到三电平硬件</strong><br> 原二电平代码输出 <code>duty_a/duty_b/duty_c</code>，硬件升级为三电平 NPC 后，工程师尝试把 duty 解释为上管占空比，结果 O 状态不可控，中点电压快速漂移。</p></blockquote><blockquote><p><strong>场景 2：相同目标电压有多组开关状态</strong><br> 在某些小矢量位置，正小矢量和负小矢量产生同样的空间电压，却对中点电容充放电方向相反。只按“合成电压正确”选矢量，会让母线中点逐渐失衡。</p></blockquote><blockquote><p><strong>场景 3：过调制边界不再清楚</strong><br> 二电平 SVPWM 中调制比接近极限时，只需处理作用时间溢出。三电平中还要保证小三角形判断、冗余矢量选择和 P/O/N 状态时间都合法。</p></blockquote><h3 id="核心问题" tabindex="-1">核心问题 <a class="header-anchor" href="#核心问题" aria-label="Permalink to &quot;核心问题&quot;">​</a></h3><p>三电平 SVPWM 为什么不能只是“更多矢量的二电平 SVPWM”？</p><p><strong>答案：</strong> 因为三电平调制同时承担两个目标：合成目标电压和管理中点电位。二电平调制只需要输出平均占空比，三电平调制必须显式表达状态序列和冗余矢量选择。</p><h3 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h3><p>读完本模块，你将能够：</p><p>说明三电平空间矢量比二电平多在哪里<br> 区分大矢量、中矢量、小矢量和零矢量<br> 理解小三角形分区与作用时间计算的关系<br> 解释冗余小矢量如何参与中点平衡<br> 设计面向 lxfoc 扩展的三电平调制接口草案</p><hr><h2 id="_3-直观理解" tabindex="-1">3. 直观理解 <a class="header-anchor" href="#_3-直观理解" aria-label="Permalink to &quot;3.  直观理解&quot;">​</a></h2><h3 id="_3-1-从二电平-svpwm-到三电平-svpwm" tabindex="-1">3.1 从二电平 SVPWM 到三电平 SVPWM <a class="header-anchor" href="#_3-1-从二电平-svpwm-到三电平-svpwm" aria-label="Permalink to &quot;3.1 从二电平 SVPWM 到三电平 SVPWM&quot;">​</a></h3><p>二电平 SVPWM 在 alpha-beta 平面中用 6 个有效矢量和 2 个零矢量合成目标电压。每相只有 P/N 两种状态，因此三相组合共有 <code>2^3 = 8</code> 种开关状态。</p><p>三电平 SVPWM 将每相状态扩展为 P/O/N，三相组合变为 <code>3^3 = 27</code> 种。不同组合可能映射到同一个空间矢量，因此出现冗余矢量。</p><h3 id="_3-2-四类空间矢量" tabindex="-1">3.2 四类空间矢量 <a class="header-anchor" href="#_3-2-四类空间矢量" aria-label="Permalink to &quot;3.2 四类空间矢量&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>类型</th><th>典型特征</th><th>调制作用</th></tr></thead><tbody><tr><td>大矢量</td><td>靠近外六边形顶点</td><td>决定高调制比下的边界</td></tr><tr><td>中矢量</td><td>位于外六边形边附近</td><td>参与扇区内目标矢量合成</td></tr><tr><td>小矢量</td><td>靠近中心，通常有冗余状态</td><td>合成电压并调节中点电位</td></tr><tr><td>零矢量</td><td>输出空间电压为 0</td><td>分配零电压时间、影响共模行为</td></tr></tbody></table></div><h3 id="_3-3-小三角形" tabindex="-1">3.3 小三角形 <a class="header-anchor" href="#_3-3-小三角形" aria-label="Permalink to &quot;3.3 小三角形&quot;">​</a></h3><p>三电平 SVPWM 的一个扇区通常继续划分为多个小三角形。目标矢量落在哪个小三角形，就选择该小三角形的三个顶点矢量进行时间合成。</p><p>合成原则仍然是伏秒平衡：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vref * Ts = V1 * T1 + V2 * T2 + V3 * T3</span></span>
<span class="line"><span>T1 + T2 + T3 = Ts</span></span>
<span class="line"><span>T1 &gt;= 0, T2 &gt;= 0, T3 &gt;= 0</span></span></code></pre></div><p>如果计算出负作用时间，通常说明小三角形判断错误、坐标变换错误或目标矢量已经越界。</p><hr><h2 id="_4-技术原理" tabindex="-1">4. 技术原理 <a class="header-anchor" href="#_4-技术原理" aria-label="Permalink to &quot;4.  技术原理&quot;">​</a></h2><h3 id="_4-1-矢量分区" tabindex="-1">4.1 矢量分区 <a class="header-anchor" href="#_4-1-矢量分区" aria-label="Permalink to &quot;4.1 矢量分区&quot;">​</a></h3><p>三电平 SVPWM 的第一步不是计算 duty，而是定位目标矢量：</p><ol><li>根据 <code>atan2(u_beta, u_alpha)</code> 判断大扇区。</li><li>在扇区内用归一化坐标判断小三角形。</li><li>查表得到该小三角形的三个相邻矢量。</li><li>根据伏秒平衡计算作用时间。</li></ol><p>内容验收：</p><div class="kb-table-scroll"><table><thead><tr><th>小节</th><th>必须讲清楚的问题</th><th>验收标准</th></tr></thead><tbody><tr><td>矢量分区</td><td>大矢量、中矢量、小矢量、零矢量的位置</td><td>能画出扇区与小三角形划分</td></tr><tr><td>矢量合成</td><td>目标矢量落在哪个小三角形，如何计算作用时间</td><td>任意测试点作用时间非负且总和等于采样周期</td></tr><tr><td>冗余小矢量</td><td>正/负小矢量对中点电压的影响</td><td>中点偏差为正/负时选择方向正确</td></tr><tr><td>过调制边界</td><td>线性区、过调制区、六步边界</td><td>不出现占空比或作用时间溢出</td></tr></tbody></table></div><h3 id="_4-2-冗余小矢量与中点平衡" tabindex="-1">4.2 冗余小矢量与中点平衡 <a class="header-anchor" href="#_4-2-冗余小矢量与中点平衡" aria-label="Permalink to &quot;4.2 冗余小矢量与中点平衡&quot;">​</a></h3><p>同一个空间小矢量可能由两组不同 P/O/N 状态产生。这两组状态对输出线电压等效，但对中点电流不同。调制器可以根据 <code>neutral_error = Vdc_upper - Vdc_lower</code> 选择冗余状态：</p><ul><li>当上电容电压偏高时，优先选择能降低上电容电压或提高下电容电压的状态。</li><li>当下电容电压偏高时，选择相反方向的状态。</li><li>当中点偏差接近 0 时，可以按损耗、开关次数或共模电压优化。</li></ul><h3 id="_4-3-状态序列" tabindex="-1">4.3 状态序列 <a class="header-anchor" href="#_4-3-状态序列" aria-label="Permalink to &quot;4.3 状态序列&quot;">​</a></h3><p>状态序列需要满足：</p><ul><li>相邻状态切换尽量少，降低开关损耗。</li><li>不产生非法直通路径。</li><li>保持三相输出对称，降低低频谐波。</li><li>给电流采样留出稳定窗口。</li></ul><p>三电平调制的状态序列设计是算法、PWM 外设和驱动保护共同决定的，不应只在数学层面完成。</p><h3 id="_4-4-三电平调制接口草案" tabindex="-1">4.4 三电平调制接口草案 <a class="header-anchor" href="#_4-4-三电平调制接口草案" aria-label="Permalink to &quot;4.4 三电平调制接口草案&quot;">​</a></h3><p>未来如果 lxfoc 扩展三电平调制，建议保持与二电平 SVPWM 分离：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ualpha;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ubeta;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> vbus;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> neutral_error;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ta_p, ta_o, ta_n;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tb_p, tb_o, tb_n;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tc_p, tc_o, tc_n;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lxfoc_transform_svpwm_3level_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>接口验收：</p><ul><li>输入仍为 <code>u_alpha/u_beta/vbus</code>，保证可接 FOC 输出。</li><li>输出显式表达每相 P/O/N 时间，避免把三电平调制压扁成二电平 duty。</li><li><code>neutral_error</code> 只影响冗余状态选择，不改变目标电压矢量。</li></ul><hr><h2 id="_5-交叉视角" tabindex="-1">5. 交叉视角 <a class="header-anchor" href="#_5-交叉视角" aria-label="Permalink to &quot;5.  交叉视角&quot;">​</a></h2><h3 id="_5-1-与-pp-08-的关系" tabindex="-1">5.1 与 PP-08 的关系 <a class="header-anchor" href="#_5-1-与-pp-08-的关系" aria-label="Permalink to &quot;5.1 与 PP-08 的关系&quot;">​</a></h3><p>PP-08 解释“硬件为什么能输出 P/O/N”，本模块解释“软件如何安排 P/O/N 的时间”。没有 PP-08 的中点电流路径理解，三电平 SVPWM 很容易被误解为单纯的空间矢量查表。</p><h3 id="_5-2-与-foc-的关系" tabindex="-1">5.2 与 FOC 的关系 <a class="header-anchor" href="#_5-2-与-foc-的关系" aria-label="Permalink to &quot;5.2 与 FOC 的关系&quot;">​</a></h3><p>FOC 不关心最终桥臂是二电平还是三电平，它只输出电压矢量。但调制层必须把 <code>u_alpha/u_beta</code> 转成硬件可执行的桥臂状态。三电平调制层应作为 FOC 和 PWM 外设之间的独立边界。</p><h3 id="_5-3-与采样和保护的关系" tabindex="-1">5.3 与采样和保护的关系 <a class="header-anchor" href="#_5-3-与采样和保护的关系" aria-label="Permalink to &quot;5.3 与采样和保护的关系&quot;">​</a></h3><p>电流采样窗口、死区补偿、过流保护、故障关断都依赖实际开关状态。三电平 SVPWM 的输出如果只保留平均 duty，会丢失保护系统需要的状态信息。</p><hr><h2 id="_6-工程案例" tabindex="-1">6. 工程案例 <a class="header-anchor" href="#_6-工程案例" aria-label="Permalink to &quot;6.  工程案例&quot;">​</a></h2><h3 id="案例-三电平-npc-调制仿真" tabindex="-1">案例：三电平 NPC 调制仿真 <a class="header-anchor" href="#案例-三电平-npc-调制仿真" aria-label="Permalink to &quot;案例：三电平 NPC 调制仿真&quot;">​</a></h3><p><strong>目标：</strong> 对同一 <code>u_alpha/u_beta</code> 轨迹，比较二电平 SVPWM 和三电平 SVPWM 的相电压、线电压和中点电压偏差。</p><p>推荐仿真参数：</p><div class="kb-table-scroll"><table><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td><code>Vdc</code></td><td>400 V</td></tr><tr><td><code>fsw</code></td><td>20 kHz</td></tr><tr><td><code>m</code></td><td>0.2, 0.6, 0.9, 1.05</td></tr><tr><td>负载</td><td>三相 RL 或 PMSM 等效电感</td></tr></tbody></table></div><p>输出波形必须包含：</p><ul><li>三相相电压。</li><li>线电压。</li><li>中点电压偏差。</li><li>三相电流。</li><li>与二电平 SVPWM 的 THD 对比。</li></ul><p><strong>验收标准：</strong></p><div class="kb-table-scroll"><table><thead><tr><th>场景</th><th>通过标准</th></tr></thead><tbody><tr><td>低调制比 <code>m = 0.2</code></td><td>P/O/N 时间非负，波形无低频畸变</td></tr><tr><td>中调制比 <code>m = 0.6</code></td><td>中点偏差不单调漂移</td></tr><tr><td>高调制比 <code>m = 0.9</code></td><td>作用时间不溢出，线电压 THD 低于二电平基线</td></tr><tr><td>过调制探索 <code>m = 1.05</code></td><td>明确标注越界或进入过调制逻辑，不静默输出非法状态</td></tr></tbody></table></div><hr><h2 id="_7-实践练习" tabindex="-1">7. 实践练习 <a class="header-anchor" href="#_7-实践练习" aria-label="Permalink to &quot;7.  实践练习&quot;">​</a></h2><h3 id="练习-1-组合数量" tabindex="-1">练习 1：组合数量 <a class="header-anchor" href="#练习-1-组合数量" aria-label="Permalink to &quot;练习 1：组合数量&quot;">​</a></h3><p>二电平三相桥臂有多少种开关状态？三电平三相桥臂有多少种？</p><p><strong>参考答案：</strong></p><p>二电平为 <code>2^3 = 8</code> 种，三电平为 <code>3^3 = 27</code> 种。</p><h3 id="练习-2-冗余矢量意义" tabindex="-1">练习 2：冗余矢量意义 <a class="header-anchor" href="#练习-2-冗余矢量意义" aria-label="Permalink to &quot;练习 2：冗余矢量意义&quot;">​</a></h3><p>为什么两个开关状态可能产生同一个空间矢量，却不能随意二选一？</p><p><strong>参考答案：</strong></p><p>它们对线电压等效，但对中点电容充放电方向、器件损耗和开关次数可能不同。选择冗余状态时必须考虑中点电位平衡和工程约束。</p><h3 id="练习-3-作用时间检查" tabindex="-1">练习 3：作用时间检查 <a class="header-anchor" href="#练习-3-作用时间检查" aria-label="Permalink to &quot;练习 3：作用时间检查&quot;">​</a></h3><p>如果某个目标矢量计算出 <code>T1 &lt; 0</code>，最可能说明什么？</p><p><strong>参考答案：</strong></p><p>可能是目标矢量所在小三角形判断错误、坐标归一化错误，或者目标矢量超出当前线性调制区域。不能简单把负值截断为 0 后继续输出。</p><h3 id="练习-4-接口边界" tabindex="-1">练习 4：接口边界 <a class="header-anchor" href="#练习-4-接口边界" aria-label="Permalink to &quot;练习 4：接口边界&quot;">​</a></h3><p>为什么建议新增三电平调制接口，而不是修改现有二电平 <code>lxfoc_transform_svpwm</code> 输出？</p><p><strong>参考答案：</strong></p><p>二电平接口表达的是三相平均 duty；三电平接口需要表达每相 P/O/N 时间、中点误差和冗余状态选择。强行复用会让调用者误以为两者语义相同，增加硬件适配风险。</p><hr><h2 id="_8-正确性证据" tabindex="-1">8. 正确性证据 <a class="header-anchor" href="#_8-正确性证据" aria-label="Permalink to &quot;8.  正确性证据&quot;">​</a></h2><p>主要对标：</p><ul><li>Holmes and Lipo, <em>Pulse Width Modulation for Power Converters</em>.</li><li>Bose, <em>Modern Power Electronics and AC Drives</em>.</li><li>厂商三电平逆变器应用笔记中的中点平衡策略。</li></ul><p>本模块的 proof 文件位于 <code>_proofs/power-path/PP-09-Three-Level-SVPWM.module-proof.yaml</code>。</p>`,84))])}const E=r(d,[["render",n]]);export{k as __pageData,E as default};
